    if (value === 'Orbi City, блок C' || value === 'Orbi City, блок D2') return target === 'en' ? value.replace('блок', 'Block') : value.replace('блок', 'ბლოკი');
    const monthly = value.match(/^([₾$\d,–\s]+)\/месяц$/u);
